package mcp

var toolDescriptions = map[string]string{
	"xy2api.requests.search":                    "Find persisted usage and final-error rows by original request/client ID or bounded time and resource filters. Returns independent source row IDs, not a merged trace. include_recovered_upstream explicitly adds the separately authorized provider-health source; that source is not uniformly recovered. At most 100 total deduplicated source rows per page.",
	"xy2api.requests.get_detail":                "Read safe metadata for one ops_error_logs numeric error_row_id returned by request search. A client/request ID is not a row ID. Returns no error body, upstream text or inferred cross-source outcome.",
	"xy2api.requests.get_attempts":              "Read paginated SQL-projected upstream attempts for one numeric error_row_id. Row classification can require extra provider-health permission. Attempt failures do not imply a final client failure; URLs, responses and free error text are excluded.",
	"xy2api.requests.search_ingress_rejections": "Read minute-level ingress rejection aggregates by bounded time and machine reason. Counts are aggregates, not individual requests. Client IP and user/key dimensions are excluded.",
	"xy2api.accounts.search":                    "Find upstream account summaries by name, platform, status or group. Returns identifiers and safe metadata only; credentials, raw extra fields and upstream addresses are excluded.",
	"xy2api.accounts.get_health":                "Read existing account health observations for up to 100 explicit account IDs, plus stored balance snapshots. Health uses the documented fixed rolling metric windows rather than an arbitrary requested period. Balance freshness/fingerprint limitations are explicit; this never probes upstreams or reads concurrency.",
	"xy2api.groups.search":                      "Find group IDs, names, platform, status and category metadata. This does not calculate scheduling candidates or read group member users.",
	"xy2api.groups.get_usage_summary":           "Read actual_cost from persisted closed daily group rollups for a specified group. Returns only cost and daily bucket coverage; partial open days, request/token counts and live routing state are unavailable.",
	"xy2api.channels.search":                    "Find safe channel metadata and group bindings. Returns no endpoint, API key, headers or body overrides and performs no monitor probes.",
	"xy2api.channels.get_metrics":               "Read passive channel-monitor-v2 aggregates from real gateway request traffic, including counts, latency, error taxonomy and coverage/watermark.",
	"xy2api.ops.get_error_breakdown":            "Read bounded error classification aggregates and independent persisted usage-row counts. A usage row does not establish client success; source counts are not added into a client request denominator. No raw error bodies or free text.",
	"xy2api.ops.get_trends":                     "Read independent settled-usage-row and final-client-error counts in bounded time buckets with source and coverage. Rows may overlap the same request; no authoritative client denominator or success rate is inferred.",
	"xy2api.ops.get_alerts":                     "Read existing alert metadata, rule references, severity and status. Free alert descriptions are excluded; this cannot resolve, silence or change alerts.",
	"xy2api.ops.get_system_events":              "Find system event metadata by time, level, component or correlation IDs. Default window one hour, maximum six hours. Message, host, extra payload and bodies are never queried.",
	"xy2api.ops.get_realtime_snapshot":          "Read passive platform/group source-row rates and usage token aggregates for a bounded window. Settled usage and final errors remain separate; source-row rates are not authoritative client QPS. Requires both monitoring gates; no per-user/account records.",
	"xy2api.ops.get_concurrency_snapshot":       "Read current valid in-flight and waiting lease counts for one to 100 explicit account IDs and their group counts. Requires ops:view and both monitoring gates. Uses read-only Redis peek; errors are not converted to zero and stale leases are not removed.",
	"xy2api.routing.get_quality_state":          "Read this process's immutable group/account quality snapshot with sample times and stale indicators. include_policies additionally requires policy-route permission. No evaluation, policy write, cache refresh or scheduling explain is run.",
	"xy2api.users.search":                       "Find safe summaries for ordinary users, using the current operator user_search context. API-key text lookup and administrator targets are excluded; returns no email or identity secrets.",
	"xy2api.users.get_usage_summary":            "Read bounded usage aggregates for one explicitly authorized ordinary user_id. Operator target checks exclude the operator and other administrators. Does not expose account credentials or raw key values.",
	"xy2api.users.get_subscriptions":            "Read safe subscription metadata and limits for one authorized ordinary user_id. Honors the catalog users/subscriptions AnyOf plus target checks. Window normalization changes response memory only.",
	"xy2api.audit.search":                       "Read fixed management-audit metadata such as actor/target ID, operation, timestamp and HTTP status. Request/response bodies, URLs, query strings and arbitrary JSON are never queried.",
	"xy2api.security.search_prompt_audit":       "Read prompt-audit event metadata and correlation references only. Full prompts, previews, scanner evidence and other free text are excluded even for root administrators.",
	"xy2api.me.get_profile":                     "Read the authenticated user's minimal profile and balance/concurrency metadata. Never accepts another owner and returns no email, password, identity metadata or token.",
	"xy2api.me.search_usage":                    "Search only the authenticated user's persisted usage, requested model, billed tokens/cost and caller/origin group. Numeric API-key filters must belong to this user. Upstream accounts, cost and credentials are excluded.",
	"xy2api.me.get_usage_detail":                "Read one numeric usage_row_id with the authenticated owner predicate in SQL. Missing and foreign rows both return not found; no foreign entity is loaded first.",
	"xy2api.me.get_error_history":               "Read only the authenticated user's safe final-error metadata, subject to backend-mode and user-error visibility gates. No upstream accounts, attempts or error bodies.",
	"xy2api.me.get_error_detail":                "Read one numeric error_row_id with the authenticated owner predicate and user-error visibility gates. Foreign and absent records both return not found; no upstream context or body is loaded.",
	"xy2api.me.get_subscription_status":         "Read this user's paginated subscription status, expiry, group limits and period usage. Expired windows are normalized in response memory only; no reset, activation or maintenance is performed.",
	"xy2api.me.get_quota_status":                "Read this user's paginated platform quota/usage/window metadata. Expired display windows are zeroed in memory; persisted usage can lag background accounting and no refresh or reset is performed.",
}

var parameterDescriptions = map[string]string{
	"start_time":                 "Inclusive RFC3339 UTC boundary. Defaults to one hour before end_time; maximum raw window 24 hours, system events six hours.",
	"end_time":                   "Exclusive RFC3339 boundary, default current time. The returned window identifies the actual queried interval.",
	"limit":                      "Total rows across all sources, one to 100, default 20 unless the snapshot specifies otherwise.",
	"cursor":                     "Opaque signed cursor from the previous page, bound to actor/grant/tool/filters/window. Reuse original filters unchanged.",
	"error_row_id":               "Positive numeric ops_error_logs storage row ID returned by request search. Never a request/client string ID.",
	"usage_row_id":               "Positive numeric usage_logs row ID; self tools also require this row to belong to the authenticated user.",
	"account_ids":                "One to 100 unique positive account IDs. Runtime reads are limited to these explicit accounts.",
	"user_id":                    "Explicit ordinary-user target, checked against current target ACL. Self tools inject the owner and do not accept this parameter.",
	"api_key_id":                 "Numeric key ID; self queries first verify that it belongs to the authenticated user. Never a raw key.",
	"include_recovered_upstream": "Default false. Adds the separately authorized provider-health source, which can contain recovered, failed or unknown events. Same source storage rows are deduplicated before the shared page cap.",
	"include_policies":           "Default false. Adds the separately authorized policy view without loading or evaluating policy on demand.",
	"status":                     "Exact status filter; management-audit status is a decimal HTTP status string.",
}
